deck_style.css:
/* Technical deck style on Meridian: code, tables, status badges, steps, callouts and notes. */
.dk-code-dark {
  margin: 0;
  padding: var(--space-md);
  background: var(--brand-core-ink);
  border: 1px solid var(--brand-core-ink);
  border-radius: var(--radius-md);
  color: var(--brand-core-surface);
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  font-size: calc(var(--fs-body) - 2px);
  line-height: 1.6;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
/* Token spans: only inside a code block. */
.dk-code-dark .kw { color: var(--brand-core-background); font-weight: 600; }
.dk-code-dark .fn { color: var(--brand-core-background); }
.dk-code-dark .str { color: var(--brand-core-border); }
.dk-code-dark .cm { color: var(--brand-core-border); font-style: italic; }

.dk-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--fs-body);
  font-variant-numeric: tabular-nums;
}
.dk-table th {
  padding: var(--space-sm) var(--space-md);
  background: var(--brand-core-primary);
  color: var(--brand-core-background);
  font-size: var(--fs-caption);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-align: left;
  text-transform: uppercase;
}
.dk-table td {
  padding: var(--space-sm) var(--space-md);
  border-bottom: 1px solid var(--brand-core-border);
  color: var(--brand-core-text);
}
.dk-table tbody tr:nth-child(even) td { background: var(--brand-core-surface); }

.dk-badge {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: var(--fs-caption);
  font-weight: 600;
  letter-spacing: 0.04em;
  line-height: 1.6;
  text-transform: uppercase;
}
.dk-badge--measured { background: var(--brand-core-primary); color: var(--brand-core-background); }
.dk-badge--untested {
  background: var(--brand-core-surface);
  color: var(--brand-core-muted);
  border: 1px dashed var(--brand-core-muted);
}

.dk-steps { margin: 0; padding-left: 1.4em; }
.dk-steps li { margin-bottom: var(--space-sm); padding-left: 0.3em; }
.dk-steps li::marker { color: var(--brand-core-primary); font-weight: 700; }

.dk-callout {
  border-left: 4px solid var(--brand-core-primary);
  padding: var(--space-sm) var(--space-md);
  background: var(--brand-core-surface);
  color: var(--brand-core-ink);
}
.dk-note { margin: 0; font-size: var(--fs-caption); color: var(--brand-core-muted); }
